import random

# 幸运数字转盘：抽取 0~9 的数字并用七段数码管渲染

段码表 = {0: 'abcefg', 1: 'cf', 2: 'acdeg', 3: 'acdfg', 4: 'bcdf', 5: 'abdfg', 6: 'abdefg', 7: 'acf', 8: 'abcdefg', 9: 'abcdfg'}


def 抽取数字():
    """从 0~9 中等概率抽取一个数字。"""
    return random.randint(0, 9)


def 渲染数字(digit):
    """把 0~9 的数字渲染为七段数码管段码字符串。"""
    if digit not in 段码表:
        raise ValueError(f"无法渲染的数字: {digit!r}")
    return 段码表[digit]


def 转盘():
    """抽取一个幸运数字并返回其数码管段码。"""
    return 渲染数字(抽取数字())
